#[no_mangle]
pub extern "C" fn iso7816_d4_padding(v:*const i64,n:usize)->i64{if n<3||n>27||v.is_null(){return -1;}let a=unsafe{std::slice::from_raw_parts(v,n)};let(mode,block,len)=(a[0],a[1],a[2]);if mode<0||mode>2||(mode==0&&!(1..=8).contains(&block))||(mode!=0&&block!=0)||len<0||len>24||n!=len as usize+3{return -1;}let mut b=[0u8;32];for i in 0..len as usize{if !(0..=255).contains(&a[i+3]){return -1;}b[i]=a[i+3] as u8;}if mode==0{let out=(len/block+1)*block;if out>32{return -1;}b[len as usize]=128;for i in len as usize+1..out as usize{b[i]=0;}return out-len;}if mode==1{let mut i=len as isize-1;while i>=0&&b[i as usize]==0{i-=1;}return if i>=0&&b[i as usize]==128{i as i64}else{-1};}let mut marker:i64=-1;let mut zero_suffix=true;for i in (0..len as usize).rev(){if zero_suffix&&b[i]==128{marker=i as i64;}if b[i]!=0{zero_suffix=false;}}if marker>=0{len-marker}else{-1}}
